<%include("../config.inc.php");	Encabezado();%><html>	<head>		<meta http-equiv="content-type" content="text/html;charset=ISO-8859-1">		<meta name="generator" content="Adobe GoLive 6">		<title>Mesuis :: Tabla</title>				<script>			function additem(PopName,selectedValue, selectedText, PopNameThis)  			{				var boxLengthThis = PopNameThis.length;				arrSelected = new Array();				arrSelectedtext = new Array();				var count = 0;								for (i = 0; i < boxLengthThis; i++)				{					if (PopNameThis.options[i].selected)					{						arrSelected[count] = PopNameThis.options[i].value;						arrSelectedtext[count] = PopNameThis.options[i].text;																	var x;						var swc= "2";						var boxLength = PopName.length;						var j;												var isNew = true;												if (boxLength != 0)						{							for (j = 0; j < boxLength; j++)							{																thisitem = PopName.options[j].text;																if (thisitem == arrSelectedtext[count])								{																		isNew = false;									break;																}//end if (thisitem == arrSelectedtext[count])														}//end for (j = 0; j < boxLength; j++)												}//end if (boxLength != 0)												if (isNew)						{							opener.document.frm.Tabla.value = arrSelected[count];							opener.document.frm.Tabla.text = arrSelectedtext[count];												  		opener.addSelect(arrSelectedtext[count],arrSelected[count],swc);						}//end if (isNew)											count++;										}//end if (PopNameThis.options[i].selected)									}//end for (i = 0; i < boxLengthThis; i++) 							}//end function additem(PopName,selectedValue, selectedText, PopNameThis)		</script>			</head>	<body bgcolor="#ffffff" leftmargin="0" marginheight="0" marginwidth="0" topmargin="0">		<table width="100%" cellpadding="3" cellspacing="0" border="0" align=center>			<tr>				<th class="content" align="left"><strong><font color="white"><%pv($app_title);%> :: Tablas</font></strong></th>			</tr>		</table>		<link rel="stylesheet" href="../styles.css" type="text/css">		<%		$TitleMod ="Tabla";		$MOD = "busuario";		$Table = "Tabla";		$TableJoin = "";		$Key = "IDTabla";		$KeyLength = 15;		$permisos = get_permiso($ID_Usuario,$m,$Table);if($permisos[0] >= 2){		switch (nvl($action)) {			case "insert" :					$query_subespecialidad = db_query("SELECT * FROM ModuloSite_Tabla WHERE IDModuloSite = '$id' AND IDTabla = '$idTabla'");					if( db_num_rows( $query_subespecialidad )  == 0)					{						db_query("INSERT INTO ModuloSite_Tabla VALUES ('$idTabla','$id','S')");						echo "<script>window.close();</script>";					}					else					{						window_alert($messages['SubEspModuloSite']);						list_r();					}													break;			case "list" :					$sql = make_qry_string_repuestos($HTTP_GET_VARS);					list_r($sql);			break;			default : 					list_r();			break;				} // End switch}//end if(permisos[0] > 2)else	echo Mensaje_Info("No tiene Permisos Suficientes","col2");/****************************************************************************** * FUNCTIONS *****************************************************************************/function make_qry_string_repuestos($frm){	GLOBAL $Table,$TableJoin;		$select = "Select * From $Table ";			if(!empty($frm['field']))			$where = " Where $frm[field] LIKE '$frm[QryString]%' ORDER BY Descripcion ASC ";		$qry_string = $select.$where;return $qry_string;}	/*******************************************************************************************		funcion Listar*******************************************************************************************/	function list_r($sql=""){		Global $dblink,$TitleMod,$MOD,$Table,$Key,$campo,$form,$id;				if(!empty($sql)){			$nav = new buildNav;		$nav->offset = 'offset';   		$nav->number_type = 'number';// (or 'alpha' 'number')   		$nav->limit = 1000;   		$nav->execute($sql,$dblink);		$total_records =  $nav->total_result;		$rows = $nav->rows;		$result = $nav->sql_result;		$row = $offset;				$startrow = $offset + 1;		$finalrow = ($row * $nav->limit) + $rows;		 	$pages = $nav->show_num_pages('&laquo;','&laquo; prev','&raquo;','next &raquo;','|','class=navvar');   // show pages				$info = $nav->show_info(); 	} // if(!empty($sql)){ %>							<%					if(!empty($sql)){					%>						<table width="200" border="0" cellspacing="1" cellpadding="0" class=bordertable align=center> 												<form name=Form action="" method="get">								<tr>									<th class="content">Tabla</td>								</tr>																							<tr>								<td align="center" nowrap class="content" onmouseover="this.style.cursor='hand'">										<select name=P1 size="10" multiple>										<? 										while ( $r = db_fetch_object( $result ) )										{?>											<option value="<?=$r->IDTabla?>"><?=$r->Descripcion?></b></option>										<?										}//END while										?>										</select><br>									<input type="button" value="Agregar" onclick="if(document.Form.P1.selectedIndex >= 0)additem(window.opener.document.frm.Tabla,Form.P1.options[Form.P1.selectedIndex].value,Form.P1.options[Form.P1.selectedIndex].text,document.Form.P1);">									<input type="button" value="Cerrar" onclick="window.close();">										</td>							</tr>						</form>						</table>						<br>					<%					}//end if(!empty($sql))					%>					<table align=center class=bordertable>						<form action="<?=$PHP_SELF?>" method=get>							<tr>								<td class="content" colspan="3" nowrap>Buscar Por  :										<select name="field">											<option value="IDTabla">IDTabla</option>											<option selected value="Descripcion">Descripcion</option>										</select>									<input class="text" type="text" size="18" name="QryString"><input type="hidden" name="action" value="list">									<input type="hidden" name="mod" value="busuario">									<input type="hidden" name="campo" value="<%=$campo%>">									<input type="hidden" name="id" value="<%=$id%>">									<input type="hidden" name="form" value="<%=$form%>">									<input type="submit" name="submit" value="Buscar" class="submit">								</td>							</tr>						</form>					</table>					<% 			}// Enf function list()				%></body></html>